# Let me try one more approach:
# What if each input row with 9s doesn't transform, but RATHER:
# The output shows what the FULL step-2 pattern would look like IF we had ALL rows filled

# Or maybe: only SOME rows should show the filled pattern
# Rows 0, 1, 4, 6, 7, 9, 12, 13 have some 9s
# But maybe the OUTPUT should only fill rows that have 2 9s (rows 1 and 13)

# Let me just try: rows with exactly 2 9s → full pattern, others unchanged
def output_rows_with_2_nines():
    out = [[6]*15 for _ in range(14)]
    for r in range(14):
        nine_pos = [c for c, v in enumerate(input_grid[r]) if v == 9]
        if len(nine_pos) == 2:
            # Fill step-2 from min 9s position to complete
            min_c = nine_pos[0]
            for c in range(15):
                dist_from_min = abs(c - min_c)
                if dist_from_min % 2 == 0 and dist_from_min <= 6:
                    out[r][c] = 9
        else:
            copy = input_grid[r]
            out[r] = copy
    return out

print("Only rows with 2 nines fill:")
for row in output_rows_with_2_nines():
    print(row)

# Also: fill ALL rows that have any 9s, to full step-2 pattern from col=1
def output_fill_rows_with_any():
    out = [[6]*15 for _ in range(14)]
    for r in range(14):
        nine_pos = [c for c, v in enumerate(input_grid[r]) if v == 9]
        if nine_pos:
            # Fill from col 1 (standard) to 13, all odd columns = [1,3,5,7,9,11,13]
            for c in range(1, 15, 2):
                out[r][c] = 9
        else:
            copy = input_grid[r]
            out[r] = copy
    return out

print("\n\nRows with any 9s fill to [1,3,5,7,9,11,13]:")
for row in output_fill_rows_with_any():
    print(row)

# Aha! Rows 1 and 13 in input have [1,3] which is the "minimal" step-2 pattern
# Maybe the rule is: extension to full pattern happens for rows that have [1,3]

output = [[6]*15 for _ in range(14)]
for r in [1, 13]:
    for c in range(1, 15, 2):
        out[r][c] = 9

print("Only rows 1 and 13 fill to full step-2:")
for row in output:
    print(row)

