def output_extend_from_min():
    out = [[6]*15 for _ in range(14)]
    for r in range(14):
        nine_pos = [c for c, v in enumerate(input_grid[r]) if v == 9]
        if nine_pos:
            min_c = nine_pos[0]
            max_c = nine_pos[-1]
            # Fill from min_c to max_c with step 2
            for c in range(min_c, max_c + 2, 2):
                if c < 15:
                    out[r][c] = 9
        else:
            out[r] = input_grid[r]  # keep empty
    return out

print("Extend each row from min to max with step-2:")
for row in output_extend_from_min():
    print(row)

# Also: what if the extension goes beyond max_c to create "full" pattern?
def output_extend_beyond_max():
    out = [[6]*15 for _ in range(14)]
    for r in range(14):
        nine_pos = [c for c, v in enumerate(input_grid[r]) if v == 9]
        if nine_pos:
            min_c = nine_pos[0]
            max_c = nine_pos[-1]
            # Extend from min to 14 (end) with step 2
            for c in range(min_c, 15, 2):
                out[r][c] = 9
        else:
            out[r] = input_grid[r]
    return out

print("\n\nExtend each row from min to 14 with step-2:")
